const STORAGE_KEY = 'lida-app-state-v2';
function readState() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
    const posts = Array.isArray(saved.posts) ? saved.posts.filter(p => !samplePostIds.has(p.id) && p.id !== 'lida-welcome-post') : [];
    const storedConversations = Array.isArray(saved.conversations) ? saved.conversations.filter(c => !sampleChatIds.has(c.id)) : [];
    // Seed LIDA's welcome conversation only once. Keep a deletion marker so it never
    // reappears automatically after the user intentionally deletes it.
    const hasWelcomeConversation = storedConversations.some(c => c.id === lidaWelcomeChat.id);
    const conversations = (!saved.lidaWelcomeDeleted && !hasWelcomeConversation)
      ? [lidaWelcomeChat, ...storedConversations]
      : storedConversations;
    const statuses = Array.isArray(saved.statuses) ? saved.statuses.filter(status => !['s1', 's2'].includes(status.id)) : [];
    return { ...saved, posts: [demoPosts[0], ...posts], conversations, statuses };
  } catch { return { posts: demoPosts, conversations: [lidaWelcomeChat] }; }
}
function persistState(patch) { const next = { ...readState(), ...patch }; localStorage.setItem(STORAGE_KEY, JSON.stringify(next)); return next; }
async function hashDemoPassword(password, salt) { const bytes = new TextEncoder().encode(`${salt}:${password}`); const digest = await crypto.subtle.digest('SHA-256', bytes); return [...new Uint8Array(digest)].map(b => b.toString(16).padStart(2, '0')).join(''); }
