  const [search, setSearch] = useState(''); const [active, setActive] = useState(null); const [menu, setMenu] = useState(null); const conversationPressTimer = useRef(null); const [filter, setFilter] = useState('Todos'); const [showContact, setShowContact] = useState(false);
